mapper.select:
/* selectBuyerWmGrWarehousingTotList */ SELECT X.BUYER , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BUYER) AS BUYER_NAME , X.REQ_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = X.BUYER AND CODE = X.REQ_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME
, X.BUDGET_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = X.BUYER AND CODE = X.BUDGET_DEPT AND TYPE = 'C001') AS BUDGET_DEPT_NAME , X.ACCOUNT_TYPE , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = X.BUYER AND CODE = X.ACCOUNT_TYPE AND TYPE = 'Z014') AS ACCOUNT_NAME
, X.REF_PR_NO
, X.GR_AMT , X.AR_BILL_FLAG FROM ( SELECT GR.BUYER , PR.REQ_DEPT
, PR.BUDGET_DEPT , PO.ACCOUNT_TYPE
, PR.REF_PR_NO
, SUM(GR.ITEM_AMT) AS GR_AMT , GR.AR_BILL_FLAG FROM ICOMGRDT GR , ICOMPODT PO , ICOMPRDT PR WHERE 1=1 AND GR.BUYER = PO.BUYER AND GR.PO_NO = PO.PO_NO AND GR.PO_SEQ = PO.PO_SEQ AND PO.BUYER = PR.BUYER AND PO.PR_NO = PR.PR_NO AND PO.PR_SEQ = PR.PR_SEQ AND GR.STATUS <> 'D' AND PO.STATUS <> 'D' AND PR.STATUS <> 'D' AND GR.BUYER = #{st_com_code} AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PR.REQ_DEPT = #{st_req_dept_code}
AND GR.AR_BILL_FLAG = #{st_closing_yn}
GROUP BY GR.BUYER, PR.REQ_DEPT, PR.BUDGET_DEPT, PO.ACCOUNT_TYPE, GR.AR_BILL_FLAG
GROUP BY GR.BUYER, PR.REQ_DEPT, PR.REF_PR_NO, GR.AR_BILL_FLAG
GROUP BY GR.BUYER, PR.REQ_DEPT, GR.AR_BILL_FLAG
) X

/* selectBuyerWmGrWarehousingTotList_v2 */ SELECT X.BUYER , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BUYER) AS BUYER_NAME , X.REQ_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = X.BUYER AND CODE = X.REQ_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME
, X.BUDGET_DEPT , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = X.BUYER AND CODE = X.BUDGET_DEPT AND TYPE = 'C001') AS BUDGET_DEPT_NAME , X.ACCOUNT_TYPE , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = X.BUYER AND CODE = X.ACCOUNT_TYPE AND TYPE = 'Z014') AS ACCOUNT_NAME
, X.REF_PR_NO
, X.GR_AMT , X.AR_BILL_FLAG FROM ( SELECT GR.BUYER , PR.REQ_DEPT
, PR.BUDGET_DEPT , PO.ACCOUNT_TYPE
, PR.REF_PR_NO
, SUM(GR.ITEM_AMT) AS GR_AMT , GR.AR_BILL_FLAG FROM ICOMGRDT GR , ICOMPODT PO , ICOMPRDT PR WHERE 1=1 AND GR.BUYER = PO.BUYER AND GR.PO_NO = PO.PO_NO AND GR.PO_SEQ = PO.PO_SEQ AND PO.BUYER = PR.BUYER AND PO.PR_NO = PR.PR_NO AND PO.PR_SEQ = PR.PR_SEQ AND GR.STATUS <> 'D' AND PO.STATUS <> 'D' AND PR.STATUS <> 'D' AND GR.BUYER = #{st_com_code} AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PR.REQ_DEPT = #{st_req_dept_code}
AND GR.AR_BILL_FLAG = #{st_closing_yn}
GROUP BY GR.BUYER, PR.REQ_DEPT, PR.BUDGET_DEPT, PO.ACCOUNT_TYPE, GR.AR_BILL_FLAG
GROUP BY GR.BUYER, PR.REQ_DEPT, PR.REF_PR_NO, GR.AR_BILL_FLAG
GROUP BY GR.BUYER, PR.REQ_DEPT, GR.AR_BILL_FLAG
) X
